const express = require('express');
const { propagation, context } = require('@opentelemetry/api');
const { verifyJwt } = require('../auth/jwt');
const { Invoice } = require('../models/invoice');

const app = express();

app.get('/api/billing/invoices', verifyJwt, async (req, res) => {
  // Enforce tenant authorization strictly from verified JWT claims
  const verifiedTenantId = req.user.tenantId;
  if (!verifiedTenantId) {
    return res.status(401).json({ error: 'Unauthorized: Missing tenant in token' });
  }

  const invoices = await Invoice.findAll({
    where: { tenantId: verifiedTenantId }
  });

  res.json({ tenantId: verifiedTenantId, invoices });
});

module.exports = app;
